function newsCard(array $p,string $extra=''):string{$cv=Helper::cover($p['featured_image']??'','berita-'.$p['slug'],800,520);return '<article class="group bg-white dark:bg-slate-800 rounded-2xl border overflow-hidden card-hover reveal '.$extra.'"><a href="'.Helper::url('berita/'.$p['slug']).'" class="block overflow-hidden"><img src="'.Helper::e($cv).'" alt="'.Helper::e($p['title']).'" class="w-full h-48 object-cover group-hover:scale-105 transition duration-700" loading="lazy"></a><div class="p-4"><a href="'.Helper::url('berita?kategori='.($p['cat_slug']??'')).'" class="text-[10px] uppercase tracking-wider font-bold text-emerald-600">'.Helper::e($p['cat']??'Berita').'</a><h3 class="news-card-title font-extrabold text-lg leading-snug mt-1.5"><a href="'.Helper::url('berita/'.$p['slug']).'">'.Helper::e($p['title']).'</a></h3><p class="text-xs text-slate-400 mt-2">'.Helper::tgl($p['published_at']??$p['created_at']).' &bull; '.number_format((int)$p['views']).' dibaca</p><p class="news-card-excerpt text-sm text-slate-500 mt-2 line-clamp-2">'.Helper::e(Helper::excerpt($p['excerpt']?:$p['content'],100)).'</p></div></article>';}
function newsOverlayCard(array $p):string{$cv=Helper::cover($p['featured_image']??'','berita-'.$p['slug'],800,600);return '<a href="'.Helper::url('berita/'.$p['slug']).'" class="relative rounded-3xl overflow-hidden h-64 card-hover group block"><img src="'.Helper::e($cv).'" alt="'.Helper::e($p['title']).'" class="absolute inset-0 w-full h-full object-cover group-hover:scale-105 transition duration-500" loading="lazy"><span class="absolute inset-0 bg-gradient-to-t from-slate-950/90 via-slate-900/20 to-transparent"></span><span class="absolute bottom-0 p-4 block"><span class="text-[10px] font-bold px-2 py-0.5 rounded-full bg-white/20 text-white backdrop-blur">'.Helper::e($p['cat']??'Berita').'</span><span class="block font-bold text-white mt-1.5 line-clamp-2">'.Helper::e($p['title']).'</span><span class="block text-[11px] text-slate-300 mt-1">'.Helper::tgl($p['published_at']??$p['created_at']).'</span></span></a>';}
function newsMinimalRow(array $p):string{return '<a href="'.Helper::url('berita/'.$p['slug']).'" class="flex items-baseline gap-3 py-3.5 group"><span class="text-xs font-mono text-slate-400 shrink-0">'.Helper::tgl($p['published_at']??$p['created_at']).'</span><span class="font-bold flex-1 group-hover:text-emerald-600 transition-colors">'.Helper::e($p['title']).'</span><span class="text-[10px] font-bold px-2 py-0.5 rounded-full bg-slate-100 dark:bg-slate-700 shrink-0">'.Helper::e($p['cat']??'Berita').'</span><span class="text-emerald-600 font-bold group-hover:translate-x-1 transition-transform">→</span></a>';}
function newsHorizontalCard(array $p):string{$cv=Helper::cover($p['featured_image']??'','berita-'.$p['slug'],500,400);return '<a href="'.Helper::url('berita/'.$p['slug']).'" class="grid grid-cols-[120px_1fr] sm:grid-cols-[180px_1fr] rounded-2xl border overflow-hidden bg-white dark:bg-slate-800 card-hover"><img src="'.Helper::e($cv).'" alt="'.Helper::e($p['title']).'" class="w-full h-full min-h-36 object-cover" loading="lazy"><span class="p-4"><small class="text-emerald-600 font-bold">'.Helper::e($p['cat']??'Berita').'</small><b class="block mt-1 line-clamp-2">'.Helper::e($p['title']).'</b><small class="block text-slate-400 mt-2">'.Helper::tgl($p['published_at']??$p['created_at']).'</small></span></a>';}
function newsGrid(array $rows,string $style):string{ob_start();if($style==='masonry'){echo '<div class="columns-1 sm:columns-2 lg:columns-3 gap-5">';foreach($rows as $p)echo '<div class="break-inside-avoid mb-5">'.newsCard($p).'</div>';echo '</div>';}elseif($style==='timeline'){echo '<div class="relative ml-3 md:ml-6 border-l-2 border-emerald-200 space-y-5">';foreach($rows as $p)echo '<article class="relative pl-7"><span class="absolute -left-[9px] top-2 w-4 h-4 rounded-full bg-emerald-600 ring-4 ring-white dark:ring-slate-900"></span><div class="rounded-2xl border bg-white dark:bg-slate-800 p-4 card-hover"><small class="text-emerald-600 font-bold">'.Helper::e(Helper::tgl($p['published_at']??$p['created_at'])).' &bull; '.Helper::e($p['cat']??'Berita').'</small><h3 class="font-bold text-lg mt-1"><a href="'.Helper::url('berita/'.$p['slug']).'">'.Helper::e($p['title']).'</a></h3><p class="text-sm text-slate-500 mt-1">'.Helper::e(Helper::excerpt($p['excerpt']??$p['content']??'',120)).'</p><a href="'.Helper::url('berita/'.$p['slug']).'" class="inline-block text-emerald-600 text-sm font-bold mt-2">Baca selengkapnya &rarr;</a></div></article>';echo '</div>';}elseif($style==='overlay'){echo '<div class="grid sm:grid-cols-2 '.(count($rows)>3?'lg:grid-cols-4':'md:grid-cols-3').' gap-5">';foreach($rows as $p)echo newsOverlayCard($p);echo '</div>';}elseif($style==='minimal'){echo '<div class="divide-y divide-slate-200 dark:divide-slate-700 border-y bg-white dark:bg-slate-800 rounded-2xl px-4">';foreach($rows as $p)echo newsMinimalRow($p);echo '</div>';}elseif($style==='magazine'){if(count($rows)===1){echo '<div class="grid gap-5">'.newsCard(array_shift($rows)).'</div>';}else{$lead=array_shift($rows);$leadImg=Helper::cover($lead['featured_image']??'','berita-'.$lead['slug'],1000,700);echo '<div class="grid lg:grid-cols-5 gap-5"><a href="'.Helper::url('berita/'.$lead['slug']).'" class="lg:col-span-3 lg:row-span-2 relative min-h-[360px] rounded-3xl overflow-hidden group card-hover block"><img src="'.Helper::e($leadImg).'" alt="'.Helper::e($lead['title']).'" class="absolute inset-0 w-full h-full object-cover group-hover:scale-105 transition duration-700" loading="lazy"><span class="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-900/25 to-transparent"></span><span class="absolute bottom-0 p-6 text-white block"><span class="text-[10px] font-bold bg-emerald-600 px-2 py-1 rounded-full">'.Helper::e($lead['cat']??'Berita').'</span><strong class="block text-2xl md:text-3xl mt-3 leading-tight">'.Helper::e($lead['title']).'</strong><small class="block mt-2 text-slate-300">'.Helper::tgl($lead['published_at']??$lead['created_at']).'</small></span></a><div class="lg:col-span-2 grid gap-5">';foreach($rows as $p)echo newsHorizontalCard($p);echo '</div></div>';}}elseif($style==='horizontal'){echo '<div class="grid md:grid-cols-2 gap-5">';foreach($rows as $p)echo newsHorizontalCard($p);echo '</div>';}elseif($style==='featured'){if(count($rows)===1){echo '<div class="grid gap-5">'.newsCard($rows[0]).'</div>';}else{$f=array_shift($rows);$fc=Helper::cover($f['featured_image']??'','berita-'.$f['slug'],1000,600);echo '<div class="grid md:grid-cols-2 gap-5"><a href="'.Helper::url('berita/'.$f['slug']).'" class="relative rounded-3xl overflow-hidden min-h-[320px] flex items-end card-hover group block"><img src="'.Helper::e($fc).'" alt="'.Helper::e($f['title']).'" class="absolute inset-0 w-full h-full object-cover group-hover:scale-105 transition duration-500" loading="lazy"><span class="absolute inset-0 bg-gradient-to-t from-slate-950/90 via-slate-900/30 to-transparent"></span><span class="relative p-5 block"><span class="text-[10px] font-bold px-2 py-0.5 rounded-full bg-emerald-500 text-white">'.Helper::e($f['cat']??'Berita').'</span><span class="block font-extrabold text-white text-xl mt-2">'.Helper::e($f['title']).'</span><span class="block text-xs text-slate-300 mt-1">'.Helper::tgl($f['published_at']??$f['created_at']).' • '.Helper::e(Helper::excerpt($f['excerpt']??$f['content']??'',90)).'</span></span></a><div class="grid gap-3 content-start">';foreach($rows as $p){$cv=Helper::cover($p['featured_image']??'','berita-'.$p['slug'],400,260);echo '<a href="'.Helper::url('berita/'.$p['slug']).'" class="flex gap-3 rounded-2xl border overflow-hidden bg-white dark:bg-slate-800 card-hover p-2.5"><img src="'.Helper::e($cv).'" alt="'.Helper::e($p['title']).'" class="w-28 h-20 rounded-xl object-cover shrink-0" loading="lazy"><span class="min-w-0"><span class="block font-bold text-sm line-clamp-2">'.Helper::e($p['title']).'</span><span class="block text-[11px] opacity-60 mt-1">'.Helper::e($p['cat']??'Berita').' • '.Helper::tgl($p['published_at']??$p['created_at']).'</span></span></a>';}echo '</div></div>';}}elseif($style==='list'){echo '<div class="grid gap-2.5">';foreach($rows as $p){$cv=Helper::cover($p['featured_image']??'','berita-'.$p['slug'],400,260);echo '<a href="'.Helper::url('berita/'.$p['slug']).'" class="flex gap-3.5 items-center rounded-2xl border bg-white dark:bg-slate-800 p-3 card-hover"><img src="'.Helper::e($cv).'" alt="'.Helper::e($p['title']).'" class="w-24 h-24 md:w-28 md:h-24 rounded-xl object-cover shrink-0" loading="lazy"><span class="min-w-0 flex-1"><span class="text-[10px] font-bold px-2 py-0.5 rounded-full bg-emerald-100 dark:bg-emerald-900 text-emerald-700 dark:text-emerald-200">'.Helper::e($p['cat']??'Berita').'</span><span class="block font-bold mt-1 line-clamp-2">'.Helper::e($p['title']).'</span><span class="block text-xs opacity-60 mt-0.5">'.Helper::tgl($p['published_at']??$p['created_at']).' • '.Helper::e(Helper::excerpt($p['excerpt']??$p['content']??'',80)).'</span></span><span class="text-emerald-600 font-bold text-sm shrink-0 hidden sm:block">→</span></a>';}echo '</div>';}else{$cols=$style==='cards-2'?'md:grid-cols-2':($style==='cards-4'?'sm:grid-cols-2 lg:grid-cols-4':'md:grid-cols-3');echo '<div class="grid '.$cols.' gap-5">';foreach($rows as $p)echo newsCard($p);echo '</div>';}return ob_get_clean();}
