$nBtn=function($t,$u,$ghost=false,$target='_self'){if(!$t)return '';[$href,$auto]=Helper::menuUrl($u?:'#');$tgt=$target==='_blank'||$auto==='_blank'?' target="_blank" rel="noopener noreferrer"':'';return '<a href="'.Helper::e($href).'"'.$tgt.' class="'.($ghost?'border border-current px-5 py-2.5 rounded-xl hover:bg-white/10':'bg-emerald-600 text-white px-5 py-2.5 rounded-xl font-semibold hover:bg-emerald-500').' inline-block mt-2 mr-2">'.Helper::e($t).'</a>';};
