$nCtaBtnCls=function(string $style,bool $ghost=false,string $hover='auto'):string{$hv=in_array($hover,['auto','darken','lift','glow','zoom'],true)?$hover:'auto';$fx=$hv==='lift'?' cta-hv-lift':($hv==='glow'?' cta-hv-glow':($hv==='zoom'?' cta-hv-zoom':($hv==='darken'?' cta-hv-darken':'')));if($ghost)return 'border border-white/50 text-white px-5 py-2.5 rounded-xl hover:bg-white/15 inline-block mt-2 mr-2 font-semibold cta-btn'.$fx;return match($style){'emerald'=>'bg-emerald-600 text-white px-5 py-2.5 rounded-xl font-semibold hover:bg-emerald-500 inline-block mt-2 mr-2 shadow cta-btn'.$fx,'dark'=>'bg-slate-900 text-white px-5 py-2.5 rounded-xl font-semibold hover:bg-slate-700 inline-block mt-2 mr-2 shadow cta-btn'.$fx,'outline'=>'border-2 border-white text-white px-5 py-2.5 rounded-xl font-semibold hover:bg-white hover:text-slate-900 inline-block mt-2 mr-2 cta-btn'.$fx,'glass'=>'bg-white/15 text-white border border-white/30 backdrop-blur px-5 py-2.5 rounded-xl font-semibold hover:bg-white/25 inline-block mt-2 mr-2 cta-btn'.$fx,default=>'bg-white text-slate-900 px-5 py-2.5 rounded-xl font-bold hover:bg-slate-100 inline-block mt-2 mr-2 shadow cta-btn'.$fx,};};
$nCtaBtns=function(array $s)use($nCtaBtnCls):string{$style='white';$hover='auto';$align='center';try{$bj=json_decode((string)($s['buttons_json']??''),true);if(is_array($bj)){if(!empty($bj['cta_btn']))$style=$bj['cta_btn'];if(!empty($bj['cta_btn_hover']))$hover=$bj['cta_btn_hover'];if(!empty($bj['cta_align']))$align=$bj['cta_align'];}}catch(Throwable){}if(!in_array($style,['white','emerald','dark','outline','glass'],true))$style='white';$list=[];if(!empty($s['buttons_json'])){$jb=json_decode($s['buttons_json'],true);if(is_array($jb))foreach($jb as $b){if(is_array($b)&&(!empty($b['text'])||!empty($b['url'])))$list[]=$b;}}if(!$list){if(!empty($s['btn_text'])||!empty($s['btn_url']))$list[]=['text'=>$s['btn_text'],'url'=>$s['btn_url'],'target'=>$s['btn_target']??'_self'];if(!empty($s['btn2_text'])||!empty($s['btn2_url']))$list[]=['text'=>$s['btn2_text'],'url'=>$s['btn2_url'],'target'=>$s['btn2_target']??'_self'];}if(!$list)$list[]=['text'=>'Hubungi Kami','url'=>Helper::url('kontak'),'target'=>'_self'];$h='';foreach($list as $i=>$b){[$href,$auto]=Helper::menuUrl($b['url']??'#');$tgt=(($b['target']??'_self')==='_blank'||$auto==='_blank')?' target="_blank" rel="noopener noreferrer"':'';$h.='<a href="'.Helper::e($href).'"'.$tgt.' class="'.$nCtaBtnCls($style,$i>0,$hover).'">'.Helper::e($b['text']??'').'</a>';}return '<div class="'.($align==='left'?'mt-6 flex flex-wrap gap-3':'mt-6 flex flex-wrap justify-center gap-3').'">'.$h.'</div>';};
$nSecBtns=function($s)use($nBtn){$list=[];if(!empty($s['buttons_json'])){$jb=json_decode($s['buttons_json'],true);if(is_array($jb))foreach($jb as $b){if(!empty($b['text'])||!empty($b['url']))$list[]=$b;}}if(!$list){if(!empty($s['btn_text'])||!empty($s['btn_url']))$list[]=['text'=>$s['btn_text'],'url'=>$s['btn_url'],'target'=>$s['btn_target']??'_self'];if(!empty($s['btn2_text'])||!empty($s['btn2_url']))$list[]=['text'=>$s['btn2_text'],'url'=>$s['btn2_url'],'target'=>$s['btn2_target']??'_self'];}$h='';foreach($list as $i=>$b)$h.=$nBtn($b['text']??'',$b['url']??'',$i>0,$b['target']??'_self');return $h;};
